-- Snowflake: raw semi-structured landing table
CREATE OR REPLACE TABLE raw_orders (payload VARIANT);

INSERT INTO raw_orders
SELECT PARSE_JSON('{
  "order_id": 1001,
  "customer": { "name": "Ada", "city": "Austin" },
  "items": [
    { "sku": "A-1", "qty": 2, "price": 9.50 },
    { "sku": "B-7", "qty": 1, "price": 19.00 }
  ]
}');

-- Scalar path access + casting (colon path, dot for nested objects)
SELECT
  payload:order_id::NUMBER            AS order_id,
  payload:customer.name::STRING       AS customer_name,
  payload:customer.city::STRING       AS city,
  payload:items[0].sku::STRING        AS first_sku
FROM raw_orders;

-- Flatten the items array: one row per line item
SELECT
  o.payload:order_id::NUMBER   AS order_id,
  f.value:sku::STRING          AS sku,
  f.value:qty::NUMBER          AS qty,
  f.value:price::NUMBER        AS price,
  (f.value:qty::NUMBER * f.value:price::NUMBER) AS line_total
FROM raw_orders o,
     LATERAL FLATTEN(input => o.payload:items) f;

